// RemoveCreateEventNidEvent relationship.
// Sets o.R.CreateEventNidEvent to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Room) RemoveCreateEventNidEvent(ctx context.Context, exec boil.ContextExecutor, related *Event) error {
	var err error

	queries.SetScanner(&o.CreateEventNid, nil)
	if _, err = o.Update(ctx, exec, boil.Whitelist("create_event_nid")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.CreateEventNidEvent = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.CreateEventNidRooms {
		if queries.Equal(o.CreateEventNid, ri.CreateEventNid) {
			continue
		}

		ln := len(related.R.CreateEventNidRooms)
		if ln > 1 && i < ln-1 {
			related.R.CreateEventNidRooms[i] = related.R.CreateEventNidRooms[ln-1]
		}
		related.R.CreateEventNidRooms = related.R.CreateEventNidRooms[:ln-1]
		break
	}
	return nil
}

